css:
/* A4, measured from the paper original. Top-level .print-format margins are the
   wkhtmltopdf page margins (Frappe reads them). */
.print-format {
    margin-top: 40mm;
    margin-bottom: 20mm;
    margin-left: 25mm;
    /* 2mm less than the layout margin; see the print padding below */
    margin-right: 22mm;
    padding: 0 !important;
    font-family: "Times New Roman", "Liberation Serif", serif;
    font-size: 11pt;
    line-height: 4.6mm;
    color: #000;
}
/* Frappe reads only the top-level rule above; don't apply it again inside the page.
   The 2mm right inset absorbs wkhtmltopdf drawing text slightly wider than it laid it out,
   which otherwise clips the last letters of full-width lines at the page margin. */
@media print {
    .print-format { margin: 0 !important; }
    .document-page { padding-right: 2mm; }
}
.document-page h3 { font-size: 12pt; font-weight: bold; text-decoration: underline; text-align: center; line-height: 4.6mm; margin: 0 0 5mm; }
.document-page p { margin: 0; }
.document-page .intro { text-align: justify; margin-bottom: 4.2mm; }
.document-page table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.document-page .info td { padding: 0 !important; border: 0; vertical-align: top !important; }
.document-page .info .caption { width: 50.8mm; }
.document-page .info .colon { width: 2.5mm; }
.document-page .info .blank td { height: 4.6mm; }
.document-page .grid td { border: 1px solid #000; padding: 0.9mm 1mm !important; vertical-align: middle !important; word-wrap: break-word; }
.document-page .grid tr { page-break-inside: avoid; }
.document-page .grid .head td { text-align: center; }
.document-page .grid + .grid { margin-top: 4.7mm; }
.document-page .value { white-space: pre-wrap; word-wrap: break-word; }
.document-page .signatures { margin-top: 9.6mm; }
.document-page .signatures td { padding: 0 !important; border: 0; vertical-align: top !important; }
.document-page .signatures td.name { padding: 1.7mm 0 0 5mm !important; }
/* Browser preview: the page as an A4 sheet with the same margins. */
@media screen {
    .print-format {
        width: 210mm; max-width: none; min-height: 0;
        margin: 0 auto !important;
        background: transparent !important; box-shadow: none !important; border-radius: 0;
    }
    .document-page {
        box-sizing: border-box;
        width: 210mm;
        min-height: 297mm;
        padding: 40mm 24mm 20mm 25mm;
        margin: 0 auto 8mm;
        background: #fff;
        box-shadow: 0 1px 6px rgba(0, 0, 0, .25);
    }
}
